// Plain-data shapes of the tables generated by gen_tok2.py (the layout of tok-2 and the gesture masks).
#pragma once
#include <cstdint>
#include <string_view>

namespace em::social::tok2 {

enum class Codec : std::uint8_t { scalar, vector, symbol, bag, pointer, pointer_list, proposition };
// How a number is normalised (formulas pinned in ai/tok2/golden/layout.json). qty_signed: unit degC only.
enum class NumScale : std::uint8_t { bipolar10, unipolar10, ratio, unit, boolean, qty, qty_signed, time, time_until };

struct Component {
  std::string_view name;
  NumScale scale;
  std::uint16_t col;     // absolute column in the num block
  bool pool_sum;         // pooled by sum when several objects are held (else max)
};

struct ColumnDef {
  std::string_view name;          // field name of the record
  Codec codec;
  NumScale scale;                 // scalar only
  std::uint16_t col;              // first column in its block
  std::uint8_t width;
  bool is_enum;                   // symbol / bag of an enumeration
  bool multi;                     // vector: a list of objects, pooled
  bool utterance;                 // proposition: a full utterance (mood) instead of a bare proposition
  std::uint32_t ref_types;        // bit per type id: record types a pointer may designate (0 = any)
  std::uint16_t values_at, values_n;   // enum values (kStringStart index, count); n == 0: not checked
  std::uint16_t words_at, words_n;     // closed set of percept words; n == 0: open
  std::uint16_t comp_at, comp_n;       // vector components
};

struct TypeDef {
  std::string_view name;
  std::uint8_t id, count;         // type id (1-based), token budget
  std::string_view key;           // key prefix, or the fixed key
  bool fixed_key;
  std::uint16_t col_at, col_n;    // columns in write order
};

struct RefParamDef {
  std::string_view name;
  bool optional, accepts_direction, accepts_form, party;
  std::uint32_t type_mask;        // record types that can stand for what the parameter accepts
  std::int16_t req_col_thing, req_col_inv;   // num column of the property the object must have (-1: none)
};

struct GestureMaskDef {
  std::string_view name;
  bool contact;
  std::uint8_t n_refs;
  RefParamDef refs[3];
};

}  // namespace em::social::tok2
